CREATE OR REPLACE FUNCTION omp_control.install_workspace_rls(target regclass, workspace_column name) RETURNS void LANGUAGE plpgsql SET search_path = pg_catalog AS $$
DECLARE target_schema text; column_type regtype; nullable bool;
BEGIN
 SELECT n.nspname, a.atttypid::regtype, a.attnotnull INTO target_schema, column_type, nullable FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_attribute a ON a.attrelid=c.oid AND a.attname=workspace_column AND a.attnum>0 AND NOT a.attisdropped WHERE c.oid=target;
 IF target_schema NOT IN ('omp_control','omp_work','omp_evidence','omp_audit','omp_integration','omp_fleet') THEN RAISE EXCEPTION 'invalid RLS schema'; END IF;
 IF column_type IS DISTINCT FROM 'uuid'::regtype OR nullable IS DISTINCT FROM true THEN RAISE EXCEPTION 'workspace column must be NOT NULL UUID'; END IF;
 EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', target);
 EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY', target);
 EXECUTE format('CREATE POLICY workspace_actor_policy ON %s USING (%I = omp_control.current_workspace_id() AND omp_control.current_actor_id() IS NOT NULL) WITH CHECK (%I = omp_control.current_workspace_id() AND omp_control.current_actor_id() IS NOT NULL)', target, workspace_column, workspace_column);
END $$;

CREATE TABLE omp_control.workspaces (workspace_id uuid PRIMARY KEY, next_alias integer NOT NULL DEFAULT 1 CHECK(next_alias > 0), provenance jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE omp_control.idempotent_commands (workspace_id uuid NOT NULL REFERENCES omp_control.workspaces, operation_id uuid NOT NULL, request_id uuid NOT NULL, correlation_id uuid NOT NULL, command_type text NOT NULL, required_scope text NOT NULL, request_sha256 text NOT NULL CHECK(request_sha256 ~ '^[0-9a-f]{64}$'), state text NOT NULL CHECK(state IN ('executing','applied','rejected','pending_approval')), response jsonb, error jsonb, result_sha256 text CHECK(result_sha256 ~ '^[0-9a-f]{64}$'), attempt_count integer NOT NULL DEFAULT 1 CHECK(attempt_count BETWEEN 1 AND 3), conflict_count integer NOT NULL DEFAULT 0, diagnostics text[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT clock_timestamp(), updated_at timestamptz NOT NULL DEFAULT cloc…
SELECT omp_control.install_workspace_rls('omp_control.idempotent_commands'::regclass, 'workspace_id');

CREATE TABLE omp_work.work_items (work_id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES omp_control.workspaces, state text NOT NULL, current_revision_id uuid, current_candidate_id uuid, archived bool NOT NULL DEFAULT false, row_version integer NOT NULL DEFAULT 1, provenance jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), UNIQUE(workspace_id,work_id));
CREATE TABLE omp_work.work_aliases (work_id uuid NOT NULL REFERENCES omp_work.work_items, workspace_id uuid NOT NULL, key text NOT NULL CHECK(key ~ '^(HOME|OMP)-[1-9][0-9]*$'), primary_alias bool NOT NULL DEFAULT true, origin text NOT NULL CHECK(origin IN ('imported','local')), created_at timestamptz NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY(work_id,key), UNIQUE(workspace_id,key));

